type GetNamedSandboxParams struct {
	Name      string
	ProjectId *string
	Resume    *bool
	TeamId    *string
	Slug      *string
}

// GetNamedSandbox retrieves a named sandbox, its current session, and its exposed routes. Set `resume` to true to create a new sandbox instance from the most recent snapshot when the named sandbox is stopped; it defaults to false. The response indicates whether the sandbox resumed and includes sandbox and session details.
//
// Retrieves a named sandbox by name, including its current sandbox and routes. If the sandbox is stopped and resume is true, a new sandbox will be created from the most recent snapshot. Returns 404 if the named sandbox or its configuration no longer exists.
//
// Parameters:
//
//	name: Name for the sandbox. Must be unique per project and URL-safe
//	(alphanumeric, hyphens, underscores).
//	projectId: The project ID or name (required when not using OIDC token).
//	resume: Whether to automatically resume a stopped named sandbox by creating
//	a new instance from its snapshot. Defaults to false.
//	teamId: The Team identifier to perform the request on behalf of.
//	slug: The Team slug to perform the request on behalf of.
func GetNamedSandbox(ctx context.Context, clientConfig ClientConfig, params GetNamedSandboxParams, opts ...RequestOption) (*GetNamedSandboxResponse, error) {
	name := params.Name
	projectId := params.ProjectId
	resume := params.Resume
	teamId := params.TeamId
	slug := params.Slug

	if err := ValidateLength("name", name, LengthOpts{Max: Ptr[int](128)}); err != nil {
		return nil, err
	}
	if err := ValidatePattern("name", name, "^[a-zA-Z0-9_-]+$"); err != nil {
		return nil, err
	}

	resp, err := DoCfg[GetNamedSandboxResponse](ctx, &clientConfig, "GET", fmt.Sprintf("/v2/sandboxes/%s", EncodePathSegment(name)), &RequestOpts{
		Query: map[string]any{
			"projectId": QueryValue{Value: projectId, Style: "form", Explode: true},
			"resume":    QueryValue{Value: resume, Style: "form", Explode: true},
			"teamId":    QueryValue{Value: teamId, Style: "form", Explode: true},
			"slug":      QueryValue{Value: slug, Style: "form", Explode: true},
		},
		OperationID: "GetNamedSandbox",
		Options:     opts,
	})
	if err != nil {
		return nil, err
	}
	return &resp.Data, nil
}
